#include <bits/stdc++.h>
using namespace std;

long long powMod(long long base, long long exp, long long mod) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

long long powInverse(long long a, long long m) {
    return powMod(a, m - 2, m);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    const int MAX = 5005;
    long long S[MAX][MAX] = {0};
    long long mod = 998244353;

    S[1][1] = 1;
    S[0][0] = 0;
    for (int i = 1; i <= 5000; i++) {
        S[i][i] = 1;
        S[i][0] = 0;
    }
    for (int i = 2; i <= 5000; i++) {
        for (int j = 1; j <= i; j++) {
            S[i][j] = (S[i - 1][j] * j % mod + S[i - 1][j - 1]) % mod;
        }
    }

    long long n, m;
    int k;
    cin >> n >> m >> k;
    m = powInverse(m, mod);

    long long dp[MAX] = {0};
    dp[0] = 1;
    for (int i = 1; i <= min(n, (long long)k); i++) {
        dp[i] = (dp[i - 1] * (n - i + 1)) % mod;
    }

    long long total = 0;
    for (int i = 1; i <= min(n, (long long)k); i++) {
        long long term = (dp[i] * powMod(m, i, mod)) % mod;
        term = (term * S[k][i]) % mod;
        total = (total + term) % mod;
    }

    cout << total << "\n";

    return 0;
}
